const initialFaq = [
  {
    id: 1,
    question: 'How does Casa Verde source its seasonal ingredients?',
    answer:
      'Our kitchen leverages local farmers and producers who prioritize heirloom varieties and regenerative practices. This ensures the freshest and most flavorful ingredients, while supporting sustainable agriculture.',
    active: false,
  },
  {
    id: 2,
    question: 'What makes Casa Verde’s wood-fired pizzas so unique?',
    answer:
      'Our brick oven reaches temperatures up to 900°F, which locks in intense smokiness and unparalleled crust texture. Each pizza is hand-tossed and cooked to perfection in under 90 seconds.',
    active: false,
  },
  {
    id: 3,
    question: 'Do you offer any vegan or gluten-free options?',
    answer:
      'Absolutely! We cater to diverse dietary needs with a dedicated vegan menu and several gluten-free items. Please inform your server upon arrival so they can guide you through the offerings.',
    active: false,
  },
  {
    id: 4,
    question: 'Is Casa Verde accepting reservations for the upcoming season?',
    answer:
      'Yes, we are actively booking tables starting from the first week of April. To reserve your spot, please fill out the form on our main page or give us a call. Walk-ins are also welcome, space permitting.',
    active: false,
  },
  {
    id: 5,
    question: 'What is included in the reservation package?',
    answer:
      'For parties larger than 4, we include a complimentary bottle of natural sparkling wine, a custom cocktail menu, and priority seating at the chef’s counter. All reservations are subject to our current T&C.',
    active: false,
  },
];

export default function Faq() {
  const [expanded, setExpanded] = useState(0);

  return (
    <section className="relative bg-slate-900 p-8 sm:p-12 max-w-5xl mx-auto text-slate-100">
      <div className="absolute -top-24 -left-24 w-96 h-96 bg-white/10 pointer-events-none rounded-full blur-3xl opacity-50" />
      <div className="absolute -right-24 -bottom-24 w-96 h-96 bg-white/10 pointer-events-none rounded-full blur-3xl opacity-50" />

      <div className="mb-16 text-center">
        <div className="inline-flex items-center gap-2 rounded-full bg-white/5 p-2 text-slate-400">
          <Sparkles className="w-4 h-4" />
          <h1 className="text-xl font-bold tracking-tight text-slate-100">Frequently Asked Questions</h1>
        </div>
        <p className="mt-4 text-slate-400">Explore our answers to common queries about dining at Casa Verde.</p>
      </div>

      <div className="w-full max-w-md mx-auto grid grid-cols-1 gap-8 sm:grid-cols-2 sm:gap-12">
        {initialFaq.map((faq) => {
          return (
            <div
              key={faq.id}
              className="group relative rounded-2xl bg-white/5 p-6 backdrop-blur-xl border border-white/10 transition-all duration-300 hover:scale-[1.01] hover:shadow-2xl hover:border-white/20"
            >
              <div className="flex items-start justify-between pb-3">
                <div className="flex items-center gap-3">
                  <HelpCircle2 className="w-5 h-5 text-amber-400" />
                  <h3 className="font-semibold text-slate-200">{faq.question}</h3>
                </div>
                <button
                  onClick={() => setExpanded((prev) => (prev === faq.id ? 0 : faq.id))}
                  className="text-slate-500 hover:text-slate-200"
                >
                  <ChevronRight className={`w-4 h-4 transform transition-transform ${expanded === faq.id ? 'rotate-180' : ''}`} />
                </button>
              </div>
              {expanded === faq.id && (
                <div className="pt-6 prose prose-slate prose-a:no-underline prose-a:text-indigo-400 mx-auto max-w-sm">
                  {faq.answer}
                </div>
              )}
            </div>
          );
        })}
      </div>

      <style jsx>{`
        .group:hover .prose a {
          color: #64a3ff !important;
        }
      `}</style>
    </section>
  );
}

