export default function Menu() {
  const [searchTerm, setSearchTerm] = useState('');
  const [activeCategory, setActiveCategory] = useState('All');
  const [sortedItems, setSortedItems] = useState(items);

  const handleSearch = (e) => {
    const term = e.target.value.toLowerCase();
    setSearchTerm(term);
    if (term === '') {
      setSortedItems(items);
    } else {
      setSortedItems(items.filter(item => 
        item.name.toLowerCase().includes(term) ||
        item.description.toLowerCase().includes(term)
      ));
    }
  };

  const handleCategory = (cat) => {
    if (cat === 'All') {
      setSortedItems(items);
    } else {
      setSortedItems(items.filter(item => item.category === cat));
    }
    setActiveCategory(cat);
  };

  return (
    <div className="min-h-[80vh] bg-slate-950 text-slate-100 font-sans antialiased">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-24">
        <div className="mb-12">
          <h2 className="text-3xl font-bold tracking-tight text-slate-100 sm:text-4xl">
            <span className="inline-block bg-gradient-to-r from-indigo-600 via-purple-600 to-pink-600 text-transparent bg-clip-text animate-pulse">Casa Verde</span> &middot; Seasonal Italian Cuisine
          </h2>
          <p className="mt-4 text-slate-400 max-w-md text-base sm:text-lg">
            Experience the essence of Italian craftsmanship, where every dish tells a story of handcrafted passion.
          </p>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {sortedItems.filter(item => 
            item.name.toLowerCase().includes(searchTerm) && 
            (activeCategory === 'All' || item.category === activeCategory)
          ).map(item => (
            <div key={item.id} className="group relative flex flex-col h-full bg-slate-900 rounded-2xl border border-white/10 p-6 transition-all duration-300 hover:scale-[1.02] hover:shadow-2xl">
              <div className="relative h-48 w-full overflow-hidden rounded-t-2xl bg-black/70 transition-all duration-300 group-hover:h-56">
                <img src={item.image} alt={item.name} className="absolute inset-0 h-full w-full object-cover brightness-75 transition-opacity duration-300 group-hover:brightness-100" />
                <div className="absolute bottom-4 left-4 right-4 bg-gradient-to-t from-slate-900/80 via-slate-900/40 to-slate-900/0 opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
              </div>

              <div className="relative mt-6 flex-1 flex flex-col justify-between p-4 space-y-4">
                <div className="flex items-start justify-between">
                  <div className="space-y-1">
                    <h3 className="text-lg font-semibold text-slate-100 tracking-tight">{item.name}</h3>
                    <p className="text-sm text-slate-400">{item.category}</p>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="px-2.5 py-1 rounded-full text-xs font-semibold bg-indigo-500/20 text-indigo-400 border border-indigo-500/30">
                      {item.tags.map((tag, i) => <span key={i}>{tag}</span>)}
                    </span>
                    <span className="px-2 py-1 rounded-full text-xs font-medium bg-amber-500/20 text-amber-400 border border-amber-500/30">
                      {item.rating} <Star className="w-3.5 h-3.5" />
                    </span>
                  </div>
                </div>
                <div className="flex items-center justify-between">
                  <p className="text-xl font-semibold text-slate-100">{item.price}</p>
                  <button className="flex items-center gap-1 rounded-lg bg-white/5 px-3.5 py-2 text-sm font-medium text-slate-300 hover:bg-white/10 transition-colors active:scale-95">
                    <CheckCircle2 className="w-3.5 h-3.5" /> Add to Cart
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>

        <div className="mt-12">
          <div className="flex items-center justify-between mb-6">
            <div>
              <h3 className="text-xl font-semibold text-slate-100">Explore More</h3>
              <p className="text-slate-400 text-sm">Filter by category or use the search bar to find your perfect dish.</p>
            </div>
            <div className="flex items-center gap-3">
              <button 
                onClick={() => handleCategory('All')}
                className={`py-2 px-4 rounded-lg text-sm font-medium border border-white/10 bg-white/5 text-slate-300 hover:bg-white/10 transition-all duration-300 ${
                  activeCategory === 'All' ? 'bg-indigo-600/10 text-indigo-400 shadow-lg shadow-indigo-600/30' : 'hover:bg-white/10'
                }`}
              >
                All
              </button>
              <button 
                onClick={() => handleCategory('Pizzas')}
                className={`py-2 px-4 rounded-lg text-sm font-medium border border-white/10 bg-white/5 text-slate-300 hover:bg-white/10 transition-all duration-300 ${
                  activeCategory === 'Pizzas' ? 'bg-indigo-600/10 text-indigo-400 shadow-lg shadow-indigo-600/30' : 'hover:bg-white/10'
                }`}
              >
                Pizzas
              </button>
              <button 
                onClick={() => handleCategory('Pasta & Rice')}
                className={`py-2 px-4 rounded-lg text-sm font-medium border border-white/10 bg-white/5 text-slate-300 hover:bg-white/10 transition-all duration-300 ${
                  activeCategory === 'Pasta & Rice' ? 'bg-indigo-600/10 text-indigo-400 shadow-lg shadow-indigo-600/30' : 'hover:bg-white/10'
                }`}
              >
                Pasta & Rice
              </button>
              <button 
                onClick={() => handleCategory('Wine & Drinks')}
                className={`py-2 px-4 rounded-lg text-sm font-medium border border-white/10 bg-white/5 text-slate-300 hover:bg-white/10 transition-all duration-300 ${
                  activeCategory === 'Wine & Drinks' ? 'bg-indigo-600/10 text-indigo-400 shadow-lg shadow-indigo-600/30' : 'hover:bg-white/10'
                }`}
              >
                Wine & Drinks
              </button>
            </div>
          </div>
          <div className="relative">
            <div className="absolute top-1/2 left-6 -translate-y-1/2 bg-white/10 p-2 rounded-lg shadow-lg shadow-slate-900/30">
              <Search className="w-5 h-5 text-white" />
            </div>
            <input 
              type="text" 
              placeholder="Search dishes..."
              value={searchTerm}
              onChange={handleSearch}
              className="w-full bg-white/5 border border-white/10 p-4 pl-12 rounded-2xl text-sm focus:ring-2 focus:ring-white/30 transition-all duration-300 placeholder:text-slate-500 outline-none"
            />
          </div>
        </div>
      </div>
    </div>
  );
}

